from __future__ import annotations

import sqlite3
from pathlib import Path

from flask import Flask, flash, g, redirect, render_template, request, url_for

BASE_DIR = Path(__file__).resolve().parent
DATABASE_PATH = BASE_DIR / "data" / "users.db"

app = Flask(__name__)
app.config["SECRET_KEY"] = "development-only-change-me"

# Routes: / displays the signup form, /users lists saved users, and /query
# provides a small read-only SQL explorer for this demonstration database.

def get_db() -> sqlite3.Connection:
    """Return one SQLite connection per request."""
    if "db" not in g:
        DATABASE_PATH.parent.mkdir(exist_ok=True)
        g.db = sqlite3.connect(DATABASE_PATH)
        g.db.row_factory = sqlite3.Row
    return g.db


@app.teardown_appcontext
def close_db(_error: BaseException | None = None) -> None:
    db = g.pop("db", None)
    if db is not None:
        db.close()


def initialize_database() -> None:
    """Create the table if this is the first run."""
    DATABASE_PATH.parent.mkdir(exist_ok=True)
    with sqlite3.connect(DATABASE_PATH) as db:
        db.execute(
            """
            CREATE TABLE IF NOT EXISTS users (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                name TEXT NOT NULL,
                email TEXT NOT NULL UNIQUE,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            )
            """
        )


@app.route("/", methods=["GET", "POST"])
def signup():
    if request.method == "POST":
        name = request.form.get("name", "").strip()
        email = request.form.get("email", "").strip().lower()

        if not name or not email:
            flash("Please enter both a name and an email address.", "error")
        elif "@" not in email:
            flash("Please enter a valid email address.", "error")
        else:
            try:
                get_db().execute(
                    "INSERT INTO users (name, email) VALUES (?, ?)", (name, email)
                )
                get_db().commit()
                flash("User signed up and saved to SQLite.", "success")
                return redirect(url_for("users"))
            except sqlite3.IntegrityError:
                flash("That email address has already been registered.", "error")

    return render_template("signup.html", db_path=DATABASE_PATH)


@app.get("/users")
def users():
    rows = get_db().execute(
        "SELECT id, name, email, created_at FROM users ORDER BY id DESC"
    ).fetchall()
    return render_template("users.html", users=rows, db_path=DATABASE_PATH)


@app.route("/query", methods=["GET", "POST"])
def query():
    sql = "SELECT id, name, email, created_at FROM users ORDER BY id DESC;"
    columns: list[str] = []
    rows: list[sqlite3.Row] = []
    error = None

    if request.method == "POST":
        sql = request.form.get("sql", "").strip()
        # This throwaway demo intentionally offers raw SQL, but keeps it read-only.
        if not sql.lower().startswith("select"):
            error = "Only read-only SELECT queries are allowed here."
        else:
            try:
                cursor = get_db().execute(sql)
                columns = [item[0] for item in cursor.description or []]
                rows = cursor.fetchall()
            except sqlite3.Error as exc:
                error = str(exc)
    else:
        cursor = get_db().execute(sql)
        columns = [item[0] for item in cursor.description or []]
        rows = cursor.fetchall()

    return render_template(
        "query.html", sql=sql, columns=columns, rows=rows, error=error, db_path=DATABASE_PATH
    )


if __name__ == "__main__":
    initialize_database()
    app.run(debug=True)
